from logparse import parse_line, summarize


def test_parse_fields():
    r = parse_line('2026-03-01T10:00:00Z ERROR db timeout')
    assert r == {'ts': '2026-03-01T10:00:00Z', 'level': 'ERROR', 'msg': 'db timeout'}


def test_parse_rejects_garbage():
    assert parse_line('not a log line') is None


def test_summarize_counts(tmp_path):
    log = tmp_path / 'app.log'
    log.write_text('2026-03-01T10:00:00Z INFO a\n2026-03-01T10:00:01Z ERROR b\n2026-03-01T10:00:02Z INFO c\n')
    assert summarize(log) == {'INFO': 2, 'ERROR': 1}


def test_summarize_skips_garbage(tmp_path):
    log = tmp_path / 'app.log'
    log.write_text('garbage\n2026-03-01T10:00:00Z WARN x\n')
    assert summarize(log) == {'WARN': 1}

