import re
from collections import Counter

LINE = re.compile(r'^(\S+Z) (DEBUG|INFO|WARN|ERROR) (.*)$')


def parse_line(line):
    m = LINE.match(line.strip())
    if not m:
        return None
    ts, level, msg = m.groups()
    return {'ts': ts, 'level': level, 'msg': msg}


def summarize(path):
    counts = Counter()
    with open(path) as f:
        for line in f:
            r = parse_line(line)
            if r:
                counts[r['level']] += 1
    return dict(counts)
